mapper.update:
UPDATE wf_arbitration_run
SET detail_rank=#{r.detailRank},
    structured_gzip=#{r.structuredGzip,jdbcType=LONGVARBINARY},
    updated_at=#{now}
WHERE run_key = #{r.runKey}
  AND facts_hash = #{r.factsHash}
  AND detail_rank < #{r.detailRank}

UPDATE wf_arbitration_run
SET has_conflict=1,
    baseline_eligible=0,
    updated_at=#{now}
WHERE run_key = #{key}

mapper.select:
SELECT COUNT(*) FROM wf_arbitration_upload u
INNER JOIN wf_arbitration_run r ON r.run_key = u.run_key
WHERE u.sender_key = #{senderKey}
